{
  "mcpServers": {
    "splunk": {
      "description": "Existing Splunk MCP Server. Replace placeholders with the endpoint and encrypted token copied from the Splunk MCP Server app sample client configuration. Use SPLUNKREADY_SAIA_ENDPOINT/TOKEN, SPLUNKREADY_SAIA_MCP_URL/TOKEN, SAIA_MCP_URL/TOKEN, or SPLUNK_AI_ASSISTANT_MCP_URL/TOKEN only when SAIA hosted-model tools use a separate cloud MCP target.",
      "command": "npx",
      "args": [
        "-y",
        "mcp-remote",
        "${SPLUNKREADY_SPLUNK_MCP_URL}",
        "--header",
        "Authorization: Bearer ${SPLUNKREADY_SPLUNK_MCP_TOKEN}"
      ],
      "env": {
        "SPLUNK_MCP_URL": "${SPLUNKREADY_SPLUNK_MCP_URL}",
        "SPLUNK_MCP_TOKEN": "${SPLUNKREADY_SPLUNK_MCP_TOKEN}",
        "SPLUNKREADY_SAIA_ENDPOINT": "${SPLUNKREADY_SAIA_ENDPOINT}",
        "SPLUNKREADY_SAIA_TOKEN": "${SPLUNKREADY_SAIA_TOKEN}",
        "SPLUNKREADY_SAIA_MCP_URL": "${SPLUNKREADY_SAIA_MCP_URL}",
        "SPLUNKREADY_SAIA_MCP_TOKEN": "${SPLUNKREADY_SAIA_MCP_TOKEN}",
        "SAIA_MCP_URL": "${SAIA_MCP_URL}",
        "SAIA_MCP_TOKEN": "${SAIA_MCP_TOKEN}",
        "SPLUNK_AI_ASSISTANT_MCP_URL": "${SPLUNK_AI_ASSISTANT_MCP_URL}",
        "SPLUNK_AI_ASSISTANT_MCP_TOKEN": "${SPLUNK_AI_ASSISTANT_MCP_TOKEN}",
        "SPLUNKREADY_SAIA_REALM": "${SPLUNKREADY_SAIA_REALM}",
        "SPLUNKREADY_SAIA_TENANT": "${SPLUNKREADY_SAIA_TENANT}",
        "SPLUNKREADY_SAIA_ENABLED": "true"
      },
      "source": "Splunk MCP Server app sample client configuration using mcp-remote placeholders."
    },
    "splunkready": {
      "description": "SplunkReady Agent Readiness Compiler from a source clone. Replace cwd with the checked-out repository path until the next npm package release includes `splunkready mcp`.",
      "command": "npm",
      "args": [
        "run",
        "mcp"
      ],
      "cwd": "/path/to/SplunkReady",
      "env": {
        "NO_COLOR": "1"
      }
    }
  },
  "workflow": {
    "useSplunkFor": "Read-only investigation through the existing Splunk MCP server.",
    "useSplunkReadyFor": "Deterministic certification of the captured Splunk MCP transcript into a Readiness Receipt.",
    "certificationPrompt": "splunkready_splunk_mcp_certification_loop",
    "certificationTool": "splunkready_certify_mcp_transcript_content",
    "hostedModelDiagnosticTool": "splunkready_check_hosted_model_access",
    "hostedModelRouting": "Set SPLUNKREADY_SAIA_ENDPOINT and SPLUNKREADY_SAIA_TOKEN, or supported SAIA_MCP/SPLUNK_AI_ASSISTANT aliases, when SAIA/cloud hosted-model calls do not share the core Splunk MCP endpoint.",
    "deterministicAuthority": true,
    "mutation": false
  }
}
